sampleQueries.query:
{{graphQueriesTableName}}
| where EventType == 'CredentialStuffingEventStore'
| project TimeGenerated, Username, Score, Summary, SourceIp

{{graphQueriesTableName}}
| where EventType == 'SessionHijackingEventStore'
| project TimeGenerated, Username, CurrentIp, PreviousIp, Score, Summary

{{graphQueriesTableName}}
| where EventType == 'ApiAnomalyEventStore'
| project TimeGenerated, Username, SourceIp, RowsProcessed, Score, Summary

dataTypes.lastDataReceivedQuery:
{{graphQueriesTableName}}
 | where TimeGenerated > ago(12h) | summarize Time = max(TimeGenerated)
 | where isnotempty(Time)
